ing:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2024-08-06 12:22:28','2026-07-27 23:14:35',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (29,'hcp-simulator-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor\nchargeServer:\n  #测试配置项\n  address: ${CHARGE_SERVER_ADDRESS:http://wrt.fengzb.pp.ua:9250}','d0dc0bcc94793cc82fe3de0f7e223aa0','2024-08-06 12:26:07','2026-07-27 23:14:35',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (62,'ruoyi-gateway.yml','DEFAULT_GROUP','# 安全配置\nsecurity:\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/code\n      - /auth/logout\n      - /auth/login\n      - /auth/binding/*\n      - /auth/social/callback\n      - /auth/register\n      - /auth/tenant/list\n      - /resource/sms/code\n      - /*/v3/api-docs\n      - /*/error\n      - /csrf\n\nspring:\n  cloud:\n    # 网关配置\n    gateway:\n      # 打印请求日志(自定义)\n      requestLog: true\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: ruoyi-auth\n          uri: lb://ruoyi-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            - StripPrefix=1\n        # 代码生成\n        - id: ruoyi-gen\n          uri: lb://ruoyi-gen\n          predicates:\n            - Path=/tool/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: ruoyi-system\n          uri: lb://ruoyi-system\n          predicates:\n            - Path=/system/**,/monitor/**\n          filters:\n            - StripPrefix=1\n        # 资源服务\n        - id: ruoyi-resource\n          uri: lb://ruoyi-resource\n          predicates:\n            - Path=/resource/**\n          filters:\n            - StripPrefix=1\n        # 演示服务\n        - id: ruoyi-demo\n          uri: lb://ruoyi-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n        # MQ演示服务\n        - id: ruoyi-stream-mq\n          uri: lb://ruoyi-stream-mq\n          predicates:\n            - Path=/stream-mq/**\n          filters:\n            - StripPrefix=1\n\n    # sentinel 配置\n    sentinel:\n      filter:\n        enabled: true\n      # nacos配置持久化\n      datasource:\n        ds1:\n          nacos:\n            server-addr: ${spring.cloud.nacos.server-addr}\n            dataId: sentinel-${spring.application.name}.json\n            groupId: ${spring.cloud.nacos.config.group}\n            namespace: ${spring.profiles.active}\n            data-type: json\n            rule-type: gw-flow\n','ce06342a0e77fe4c34925fcc46be40b5','2024-01-04 09:47:55','2024-01-04 09:47:55','nacos','0:0:0:0:0:0:0:1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (65,'application-dev.yml','DEFAULT_GROUP','spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n# mail配置\n  mail:\n    host: smtp.qq.com\n    # 发送者邮箱\n    username: 544023561884@qq.com\n    # 配置密码，注意不是真正的密码，而是刚刚申请到的授权码\n    password: ENC(jsGIAOtkZ/ynRvIFfe1LPZsPGV4P6upbBdY6ylvUausBKD4zTP6ylkMAll2wR10uVbV17q5unjmB4D9wgNo0OA==)\n    # 端口号465或587\n    port: 465\n    # 默认的邮件编码为UTF-8\n    default-encoding: UTF-8\n    # 配置SSL 加密工厂\n    properties:\n      mail:\n        smtp:\n          ssl:\n            enable: true\n          socketFactoryClass: javax.net.ssl.SSLSocketFactory\n        #表示开启 DEBUG 模式，这样，邮件发送过程的日志会在控制台打印出来，方便排查错误\n        debug: true\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n      vctgo-job:\n        connectTimeout: 100000\n        readTimeout: 100000\n  compression:\n    request:\n      enabled: true\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,info\nlogging:\n  level:\n    org.springframework: info\n    com.hcp: debug\n  #log日志文件配置\n  file_basePath: ./logs\n  file_prefix: ${spring.application.name}\nmybatis-plus:\n  mapper-locations: classpath*:mapper/**/*.xml\n  global-config:\n    banner: false\n    refresh-mapper: true\n    db-config:\n      id-type: auto\n      table-underline: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n  configuration:\n    map-underscore-to-camel-case: true\n  type-handlers-package: com.hcp.common.mybatisplus\nhcp:\n  #多租户配置\n  tenant:\n    ignore-tables:\n      #系统表\n      - sys_config\n      - gen_table\n      - gen_table_column\n      - sys_dict_data\n      - sys_dict_type\n      - sys_menu\n      - sys_tenant\n      - sys_tenant_package\n      - sys_oper_log\n      - sys_logininfor\n      - branch_table\n      - global_table\n      - lock_table\n      - undo_log\n      - xxl_job_group\n      - xxl_job_info\n      - xxl_job_lock\n      - xxl_job_log\n      - xxl_job_log_report\n      - xxl_job_logglue\n      - xxl_job_registry\n      - xxl_job_user\n      - c_city\n      #自定义表\n# 短信服务\naliyun:\n  endpoint: cn-shanghai\n  accessKeyId:  \n  accessKeySecret: \n  signName:  \n  templateCode: \n# 本地文件上传    \nfile:\n  domain: http://127.0.0.1:39300\n  path: /home/upload\n  prefix: /documents\n','fb5950dd96b10da8b7afbe7fb8d1fca9','2024-08-14 23:58:56','2025-05-24 22:57:16','nacos','43.134.162.37','','hcp','通用配置','','','yaml','','');
INSERT INTO `config_info` VALUES (66,'hcp-gateway-dev.yml','DEFAULT_GROUP','spring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: hcp-auth\n          uri: lb://hcp-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 系统模块\n        - id: hcp-system\n          uri: lb://hcp-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: hcp-file\n          uri: lb://hcp-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: hcp-monitor\n          uri: lb://hcp-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: hcp-job\n          uri: lb://hcp-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: hcp-demo\n          uri: lb://hcp-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-operator\n          uri: lb://hcp-operator\n          predicates:\n            - Path=/operator/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-mp\n          uri: lb://hcp-mp\n          predicates:\n            - Path=/mp/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-simulator\n          uri: lb://hcp-simulator\n          predicates:\n            - Path=/simulator/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**\n      - /hcp-mp/**\n      - /hcp-operator/websocket/charge/**','4e76e18a44756a41678dc5be28956b3d','2024-08-14 23:58:56','2026-07-28 00:23:39',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (67,'hcp-auth-dev.yml','DEFAULT_GROUP','spring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        #loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','6509aa098761d496d08da1ca4f498f1a','2024-08-14 23:58:56','2026-07-27 23:14:35',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (68,'hcp-monitor-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      # jedis:\n      #   pool:\n      #     max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n      #     max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n      #     max-idle: 8 # 连接池中的最大  空闲连接\n      #     min-idle: 0 # 连接池中的最小空闲连接\n      lettuce:\n        pool:\n          max-active: 20\n          max-wait: 500ms\n          max-idle: 10\n          min-idle: 2\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n# seata配置\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:','e9cb9cbc34b76d05a2351bbd79390b78','2024-08-14 23:58:57','2026-07-27 23:14:35',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (69,'hcp-system-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2024-08-14 23:58:57','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (70,'hcp-gen-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n\n# 代码生成\ngen: \n  # 作者\n  author: hcp\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\n  packageName: com.hcp.system\n  # 自动去除表前缀，默认是false\n  autoRemovePre: false\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\n  tablePrefix: sys_','565487f00edae29ced6d5603504d82d7','2024-08-14 23:58:57','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (71,'hcp-file-dev.yml','DEFAULT_GROUP','#本地文件服务的配置迁移到公共配置文件里\n# FastDFS配置 -- http://hcp-fastdfs 为hosts映射\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)','1f386522103fbbb9107309f504e6d426','2024-08-14 23:58:58','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (72,'sentinel-hcp-gateway','DEFAULT_GROUP','[\n    {\n        \"resource\": \"hcp-auth\",\n        \"count\": 500,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"hcp-system\",\n        \"count\": 1000,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"hcp-gen\",\n        \"count\": 200,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    }\n]','b109301f83310c0c1bf56bfab5f4859e','2024-08-14 23:58:58','2024-08-14 23:58:58','nacos','49.118.86.41','','hcp','',NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (73,'hcp-demo-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(B0Re2bQDL0t4LztYjsoQnD5hYcCtbS39w4ZkO1yu4WMrFUvU/NbvLNgUDeNjIFHW)\n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n\nxxl:\n  job:\n    admin:\n      ### xxl-job admin address list, such as \"http://address\" or \"http://address01,http://address02\"\n      addresses: http://localhost/dev-api/job\n    ### xxl-job, access token\n    accessToken: ENC(zBN4sbqFp5WOrQLgCVvDnK/2DtXiqvO3vP2lqxNjw8Xwdlueu/12V/88OybSOAmI)\n    executor: \n      ### xxl-job executor appname\n      appname: xxl-job-executor-sample\n      ### xxl-job executor registry-address: default use address to registry , otherwise use ip:port if address is null\n      address: \n      ### xxl-job executor server-info\n      ip: 127.0.0.1\n      port: 9999\n      ### xxl-job executor log-path\n      logpath: ./logs/xxl-job\n      ### xxl-job executor log-retention-days\n      logretentiondays: 30','a742f0a6fd34431e5c715ec1292c9b1d','2024-08-14 23:58:58','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (74,'hcp-job-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi) \n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n  mail:\n    host: www.163.com\n    port: 25\n    username: xxxxxx@163.com\n    from: xxxxxx@163.com\n    password: ENC(/XMrzcND3FjY+09cZiP/sldj+Je2QtJderl3PsDHHxLLQc/a34xpK9A+he5wEAYf)\n    properties: \n      mail: \n        smtp: \n          auth: false\n          starttls: \n            enable: false\n            required: false\n          socketFactory: \n            class: javax.net.ssl.SSLSocketFactory\n          \n# swagger配置\nswagger:\n  title: 定时任务接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n\nxxl:\n  job:\n    accessToken: ENC(zBN4sbqFp5WOrQLgCVvDnK/2DtXiqvO3vP2lqxNjw8Xwdlueu/12V/88OybSOAmI)\n    i18n: zh_CN\n    logretentiondays: 30\n    triggerpool: \n      fast: \n        max: 200\n      slow: \n        max: 100\n\ncustom:\n  log:\n    list:\n      - scheduleJobQuery-error\n      - findFailJobLogIds-error\n      - findByAddressType-error\n\n','6b9737d8fd8593dd339b84a52cee50fe','2024-08-14 23:58:59','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (75,'hcp-operator-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2024-08-14 23:58:59','2026-07-27 23:14:36',NULL,'127.0.0.1','','hcp',NULL,NULL,NULL,'yaml',NULL,'');
