oup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2024-08-18 22:06:44','2026-07-27 23:14:37',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (85,'hcp-mp-local.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2024-08-18 22:06:44','2026-07-27 23:14:37',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (86,'hcp-simulator-local.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor\nchargeServer:\n  #测试配置项\n  address: ${CHARGE_SERVER_ADDRESS:http://wrt.fengzb.pp.ua:9250}','d0dc0bcc94793cc82fe3de0f7e223aa0','2024-08-18 22:06:44','2026-07-27 23:14:37',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (94,'gateway-dev.yml','DEFAULT_GROUP','spring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: hcp-auth\n          uri: lb://hcp-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: hcp-gen\n          uri: lb://hcp-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: hcp-system\n          uri: lb://hcp-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: hcp-file\n          uri: lb://hcp-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: hcp-monitor\n          uri: lb://hcp-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: hcp-job\n          uri: lb://hcp-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: hcp-demo\n          uri: lb://hcp-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-operator\n          uri: lb://hcp-operator\n          predicates:\n            - Path=/charge/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-mp\n          uri: lb://hcp-mp\n          predicates:\n            - Path=/wechat/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**\n      - /hcp-operator/**\n      - /hcp-mp/**\n      - /hcp-operator/websocket/charge/**\n      - /charge/**\n      - /wechat/**','d8ca9292e42584f7c1e23cfafd4ac4f0','2024-09-05 13:59:10','2026-07-27 23:14:37',NULL,'127.0.0.1','','70070f3a-b8c6-45f1-8056-a32a7defae98',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (95,'application-dev.yml','DEFAULT_GROUP','spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n# mail配置\n  mail:\n    host: smtp.qq.com\n    # 发送者邮箱\n    username: 544023561884@qq.com\n    # 配置密码，注意不是真正的密码，而是刚刚申请到的授权码\n    password: ENC(jsGIAOtkZ/ynRvIFfe1LPZsPGV4P6upbBdY6ylvUausBKD4zTP6ylkMAll2wR10uVbV17q5unjmB4D9wgNo0OA==)\n    # 端口号465或587\n    port: 465\n    # 默认的邮件编码为UTF-8\n    default-encoding: UTF-8\n    # 配置SSL 加密工厂\n    properties:\n      mail:\n        smtp:\n          ssl:\n            enable: true\n          socketFactoryClass: javax.net.ssl.SSLSocketFactory\n        #表示开启 DEBUG 模式，这样，邮件发送过程的日志会在控制台打印出来，方便排查错误\n        debug: true\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n      vctgo-job:\n        connectTimeout: 100000\n        readTimeout: 100000\n  compression:\n    request:\n      enabled: true\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,info\nlogging:\n  level:\n    org.springframework: info\n    com.hcp: debug\n  #log日志文件配置\n  file_basePath: ./logs\n  file_prefix: ${spring.application.name}\nmybatis-plus:\n  mapper-locations: classpath*:mapper/**/*.xml\n  global-config:\n    banner: false\n    refresh-mapper: true\n    db-config:\n      id-type: auto\n      table-underline: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n  configuration:\n    map-underscore-to-camel-case: true\n  type-handlers-package: com.hcp.common.mybatisplus\nhcp:\n  #多租户配置\n  tenant:\n    ignore-tables:\n      #系统表\n      - sys_config\n      - gen_table\n      - gen_table_column\n      - sys_dict_data\n      - sys_dict_type\n      - sys_menu\n      - sys_tenant\n      - sys_tenant_package\n      - sys_oper_log\n      - sys_logininfor\n      - branch_table\n      - global_table\n      - lock_table\n      - undo_log\n      - xxl_job_group\n      - xxl_job_info\n      - xxl_job_lock\n      - xxl_job_log\n      - xxl_job_log_report\n      - xxl_job_logglue\n      - xxl_job_registry\n      - xxl_job_user\n      - c_city\n      #自定义表\n# 短信服务\naliyun:\n  endpoint: cn-shanghai\n  accessKeyId:  \n  accessKeySecret: \n  signName:  \n  templateCode: \n# 本地文件上传    \nfile:\n  domain: http://127.0.0.1:39300\n  path: /home/upload\n  prefix: /documents\n','fb5950dd96b10da8b7afbe7fb8d1fca9','2025-05-25 00:25:19','2025-05-25 00:25:19','nacos','124.128.198.123','','b1abcbe9-3886-4726-8005-5e122e88ccb2','通用配置',NULL,NULL,'yaml',NULL,'');
