        - Path=/mp/**\n          filters:\n            - StripPrefix=1\n        - id: hcp-simulator\n          uri: lb://hcp-simulator\n          predicates:\n            - Path=/simulator/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**\n      - /hcp-mp/**\n      - /hcp-operator/websocket/charge/**','4e76e18a44756a41678dc5be28956b3d','2025-05-25 00:25:19','2026-07-28 00:23:39',NULL,'127.0.0.1','','b1abcbe9-3886-4726-8005-5e122e88ccb2',NULL,NULL,NULL,'yaml',NULL,'');
