INSERT INTO `config_info` VALUES (98,'hcp-monitor-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      # jedis:\n      #   pool:\n      #     max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n      #     max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n      #     max-idle: 8 # 连接池中的最大  空闲连接\n      #     min-idle: 0 # 连接池中的最小空闲连接\n      lettuce:\n        pool:\n          max-active: 20\n          max-wait: 500ms\n          max-idle: 10\n          min-idle: 2\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n# seata配置\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:','e9cb9cbc34b76d05a2351bbd79390b78','2025-05-25 00:25:20','2026-07-27 23:14:37',NULL,'127.0.0.1','','b1abcbe9-3886-4726-8005-5e122e88ccb2',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (99,'hcp-system-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: ENC(MTRfug5humiEOVcAc8Sx4rTwms/lJ+ix0aW9Jiw18TFbO9ledqDMl65KqdMQYUW2)\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: default_tx_group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      default_tx_group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: hcp-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: hcp-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.hcp.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: true\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.hcp.common.security.feign.FeignRequestInterceptor','c8a29cfc82a5a5ed6e8c3a98da53d55d','2025-05-25 00:25:21','2026-07-27 23:14:37',NULL,'127.0.0.1','','b1abcbe9-3886-4726-8005-5e122e88ccb2',NULL,NULL,NULL,'yaml',NULL,'');
INSERT INTO `config_info` VALUES (100,'hcp-gen-dev.yml','DEFAULT_GROUP','# spring配置\nspring: \n  data:\n    redis:\n      host: 127.0.0.1\n      port: 6379\n      database: 5\n      password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n      timeout: 1000 # 连接超时时间（毫秒）\n      jedis:\n        pool:\n          max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n          max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-idle: 8 # 连接池中的最大  空闲连接\n          min-idle: 0 # 连接池中的最小空闲连接\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://127.0.0.1:3306/vctgo_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: ENC(KvGnX7Wbi/634V32k0DIpGcwRm3+KOgrfvoyU8veNqwoLMiH6DzR/FKBkaSDlAMi)\n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By hcp\n  licenseUrl: https://hcp.cn\n\n# 代码生成\ngen: \n  # 作者\n  author: hcp\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\n  packageName: com.hcp.system\n  # 自动去除表前缀，默认是false\n  autoRemovePre: false\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\n  tablePrefix: sys_','565487f00edae29ced6d5603504d82d7','2025-05-25 00:25:21','2026-07-27 23:14:37',NULL,'127.0.0.1','','b1abcbe9-3886-4726-8005-5e122e88ccb2',NULL,NULL,NULL,'yaml',NULL,'');
